select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"id":987220003},"seq":1,"relation":"editions","after_row":{"id":987220003,"title":"In ongenade","isbn_10":"905936175X","isbn_13":"9789059361751","work_id":987120003,"cover_id":null,"language":"dut","publisher":"Cossee","publish_date":null,"open_library_edition_id":"OL39470733M"},"before_row":{"id":987220003,"title":"In ongenade","isbn_10":"905936175X","isbn_13":"9789059361751","work_id":987120003,"cover_id":null,"language":"dut","publisher":"Cosse","publish_date":null,"open_library_edition_id":"OL39470733M"}},{"key":{"work_id":987120003,"language":"nl"},"seq":2,"relation":"catalog_work_descriptions","after_row":{"text":"Na een verhouding met een studente verliest de Zuid-Afrikaanse hoogleraar David Lurie zijn baan. Hij trekt naar het afgelegen boerenbedrijf van zijn dochter Lucy en probeert daar opnieuw betekenis te vinden in hun contact. Hun manier van kijken naar de omgeving blijkt echter sterk te verschillen. Een gewelddadige gebeurtenis zet hun leven en onderlinge verhouding verder onder druk. Coetzee onderzoekt hoe Lurie omgaat met macht, verantwoordelijkheid en een samenleving waarin zijn vertrouwde opvattingen geen vanzelfsprekend gezag meer hebben.","work_id":987120003,"evidence":[{"note":"Exact Dutch paperback9789059361751 verified independently by DeSlegte and BoekenBalie; translators JoopvanHelmond/FransvanderWiel, full Disgrace1999. Exact publisher is Cossee, stored Cosse is a misspelling. Printing years2007/2009/2010 vary; no exact printing year is inferred.","type":"reviewed_identity_and_bibliography","sources":["https://www.deslegte.com/rotterdam/in-ongenade-117981/","https://boekenbalie.nl/in-ongenade/9789059361751"],"reference":"work:3310","checked_at":"2026-11-02T21:50:56.327Z","stored_fields_review":{"after":{"publisher":"Cossee"},"isbn13":"9789059361751","reason":"Exact Dutch paperback9789059361751 verified independently by DeSlegte and BoekenBalie; translators JoopvanHelmond