ps://www.deslegte.com/de-stad-en-de-honden-375505/","https://books.google.com/books/about/De_stad_en_de_honden_druk_7.html?id=jb4NGQAACAAJ"],"editionKey":"/books/OL36631149M","expectedFields":{"publisher":"De Boekerij"},"originalEditionSha256":"fba1599c6e14ad29db823514684ad69ebf9e7d1b0f9e76b7d6e9d19b40dee115"},"canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://www.deslegte.com/de-stad-en-de-honden-375505/","https://books.google.com/books/about/De_stad_en_de_honden_druk_7.html?id=jb4NGQAACAAJ","https://openlibrary.org/works/OL857544W"]},{"type":"cover_front_review","sha256":"350de512c0a0c40d9c2ed569e68e03f9214819ab2f53dbd82d70002878aa9c9a","cover_id":12524461,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/12524461-L.jpg?default=false","edition_id":987220004,"bound_title":"De stad en de honden","reviewed_at":"2026-11-02T21:50:56.327+00:00","bound_isbn13":"9789029077859","evidence_url":"https://www.deslegte.com/de-stad-en-de-honden-375505/","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12524461-M.jpg?default=false","bound_author_id":987304007},"before_row":null},{"key":{"work_id":987120005,"language":"nl"},"seq":7,"relation":"catalog_work_descriptions","after_row":{"text":"Philothei en Ibrahim groeien naar elkaar toe in een gemeenschap die door grote historische veranderingen zal worden geraakt. Verschillende bewoners vertellen hun deel van de geschiedenis, terwijl oorlog, religieuze tegenstellingen en nationalisme de onderlinge verhoudingen veranderen. Ook de opkomst van Mustafa Kemal krijgt een plaats in die bredere ontwikkeling. Louis de Bernières verbindt de persoonlijke verwachtingen van zijn personages met krachten waarover zij weinig zeggenschap hebben. Hun leefwereld laat zien hoe mensen die samenleven toch door nieuwe grenzen van elkaar kunnen worden gescheiden.","work_id":987120005,"evidence":[{"note":"Exact Dutch paperback9789029504638,565p,TinkeDavids translation of BirdsWithoutWings, independently recorded by BoekenPlatform and Bol. Listing dates2004/2005 differ, so no exact printing date is claimed. Existing Work and author retained.","type":"reviewed_identity_and_bibliography","sources":["https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","https://www.bol.com/nl/nl/p/vogels-zonder-vleugels/1001004002131120/"],"reference":"work:4176","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","https://www.bol.com/nl/nl/p/vogels-zonder-vleugels/1001004002131120/","https://openlibrary.org/works/OL1912225W"]},{"type":"cover_front_review","sha256":"1f7161cbbde833eeaecfb3513794fc1ed6d009396baecdc307653845310962fd","cover_id":12063116,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","reviewed_at":"2026-11-02T21:50:56.327+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_author_id":987320003},"before_row":null},{"key":{"edition_id":987220005},"seq":8,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987120005,"evidence":[{"note":"Exact Dutch paperback9789029504638,565p,TinkeDavids translation of BirdsWithoutWings, independently recorded by BoekenPlatform and Bol. Listing dates2004/2005 differ, so no exact printing date is claimed. Existing Work and author retained.","type":"reviewed_identity_and_bibliography","sources":["https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","https://www.bol.com/nl/nl/p/vogels-zonder-vleugels/1001004002131120/"],"reference":"work:4176","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","https://www.bol.com/nl/nl/p/vogels-zonder-vleugels/1001004002131120/","https://openlibrary.org/works/OL1912225W"]},{"type":"cover_front_review","sha256":"1f7161cbbde833eeaecfb3513794fc1ed6d009396baecdc307653845310962fd","cover_id":12063116,"reference":"cover-semantic-review-003.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"cover_url":"https://covers.openlibrary.org/b/id/12063116-L.jpg?default=false","edition_id":987220005,"bound_title":"Vogels zonder vleugels","reviewed_at":"2026-11-02T21:50:56.327+00:00","bound_isbn13":"9789029504638","evidence_url":"https://www.boekenplatform.nl/vogels-zonder-vleugels-62725","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12063116-M.jpg?default=false","bound_author_id":987320003},"before_row":null},{"key":{"work_id":987120001,"language":"nl"},"seq":9,"relation":"catalog_work_descriptions","after_row":{"text":"Martin Lynch-Gibbon denkt dat zijn huwelijk en zijn verhouding met een geliefde naast elkaar kunnen bestaan. Wanneer zijn vrouw Antonia hem verlaat voor haar psychoanalyticus, verliest hij de greep op dat geruststellende beeld. Hij probeert redelijk en beheerst te reageren, maar nieuwe ontmoetingen maken zijn emoties steeds minder overzichtelijk. Vooral een vrouw die hem eerst afstoot, oefent een onverwachte aantrekkingskracht uit. Iris Murdoch onderzoekt hoe mensen hun eigen gedrag verklaren wanneer zij niet langer bepalen welke rol zij in andermans leven spelen.","work_id":987120001,"evidence":[{"note":"Exact paperback9789021494357 independently bound to IrisMurdoch/ASeveredHead by title bibliography and DeSlegte; laterprinting variation is not a new Work. Publisher Querido and Dutch original title independently corroborated; translator H.W.J.Schaap is not a primary coauthor.","type":"reviewed_identity_and_bibliography","sources":["https://www.deslegte.com/afgehouwen-hoofd-990846/","https://www.boekbeschrijvingen.nl/murdoch-iris/murdoch.html"],"reference":"work:3172","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://www.deslegte.com/afgehouwen-hoofd-990846/","https://www.boekbeschrijvingen.nl/murdoch-iris/murdoch.html","https://openlibrary.org/works/OL1326348W"]},{"type":"cover_front_review","sha256":"5deed49c66e49e9c378d0768944240550d6502097aece1ab2e8fb238e9448ecd","cover_id":6964830,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Iris Murdoch; Een afgehouwen hoofd; Salamander. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.deslegte.com/afgehouwen-hoofd-990846/","reviewed_at":"2026-11-02T21:50:56.327+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_author_id":987309004},"before_row":null},{"key":{"edition_id":987220001},"seq":10,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987120001,"evidence":[{"note":"Exact paperback9789021494357 independently bound to IrisMurdoch/ASeveredHead by title bibliography and DeSlegte; laterprinting variation is not a new Work. Publisher Querido and Dutch original title independently corroborated; translator H.W.J.Schaap is not a primary coauthor.","type":"reviewed_identity_and_bibliography","sources":["https://www.deslegte.com/afgehouwen-hoofd-990846/","https://www.boekbeschrijvingen.nl/murdoch-iris/murdoch.html"],"reference":"work:3172","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-026.json","sources":["https://www.deslegte.com/afgehouwen-hoofd-990846/","https://www.boekbeschrijvingen.nl/murdoch-iris/murdoch.html","https://openlibrary.org/works/OL1326348W"]},{"type":"cover_front_review","sha256":"5deed49c66e49e9c378d0768944240550d6502097aece1ab2e8fb238e9448ecd","cover_id":6964830,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Iris Murdoch; Een afgehouwen hoofd; Salamander. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6964830-L.jpg?default=false","edition_id":987220001,"bound_title":"Een Afgehouwen Hoofd","reviewed_at":"2026-11-02T21:50:56.327+00:00","bound_isbn13":"9789021494357","evidence_url":"https://www.deslegte.com/afgehouwen-hoofd-990846/","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6964830-M.jpg?default=false","bound_author_id":987309004},"before_row":null},{"key":{"id":987120006},"seq":11,"relation":"works","after_row":{"id":987120006,"title":"Night Fall","cover_id":null,"author_id":987320004,"work_type":null,"source_type":null,"open_library_id":"OL22914W","first_publish_year":2004,"native_identity_key":"nlscale:fixture021:4976"},"before_row":{"id":987120006,"title":"Night Fall","cover_id":null,"author_id":987320004,"work_type":null,"source_type":null,"open_library_id":"OL22914W","first_publish_year":2001,"native_identity_key":"nlscale:fixture021:4976"}},{"key":{"work_id":987120006,"language":"nl"},"seq":12,"relation":"catalog_work_descriptions","after_row":{"text":"Een stel dat elkaar heimelijk op een strand ontmoet, filmt toevallig ook een explosie in de lucht. Ze verdwijnen met de camera voordat de politie arriveert. Vijf jaar later onderzoeken John Corey en Kate Mayfield opnieuw de ramp met TWA-vlucht 800, waarvoor een technische oorzaak is vastgesteld. In de roman vermoeden zij dat niet al het bewijs bekend is. Hun zoektocht naar de verborgen opname brengt hen tegenover mensen die haar niet willen prijsgeven. De fictieve zaak onderzoekt zo wat er gebeurt wanneer persoonlijk geheim en publiek onderzoek elkaar raken.","work_id":987120006,"evidence":[{"note":"Exact2005Dutch paperback9789044313369,TheHouseofBooks,HarryNaus translation of NightFall, bound by independent exactISBN listings. Author official bibliography confirms original book published22November2004, not stored2001; fictional investigation is not an assertion of a real cover-up.","type":"reviewed_identity_and_bibliography","sources":["https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","https://www.bol.com/nl/nl/p/de-crash/1001004002501027/"],"reference":"work:4976","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","https://www.bol.com/nl/nl/p/de-crash/1001004002501027/","https://nelsondemille.net/books/night-fall/","https://openlibrary.org/works/OL22914W"]},{"type":"cover_front_review","sha256":"e9fd7fec4c53e2d7c94d3f0370ca9399b9c893a9e0e08b128ecbce7891da0337","cover_id":12313454,"reference":"cover-semantic-review-003.json","limitation":"Nelson DeMille/De crash readable; library label and1.28MB archived source retained as quality/performance limits."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","reviewed_at":"2026-11-02T21:50:56.327+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_author_id":987320004},"before_row":null},{"key":{"edition_id":987220006},"seq":13,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":987120006,"evidence":[{"note":"Exact2005Dutch paperback9789044313369,TheHouseofBooks,HarryNaus translation of NightFall, bound by independent exactISBN listings. Author official bibliography confirms original book published22November2004, not stored2001; fictional investigation is not an assertion of a real cover-up.","type":"reviewed_identity_and_bibliography","sources":["https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","https://www.bol.com/nl/nl/p/de-crash/1001004002501027/"],"reference":"work:4976","checked_at":"2026-11-02T21:50:56.327Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-031.json","sources":["https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","https://www.bol.com/nl/nl/p/de-crash/1001004002501027/","https://nelsondemille.net/books/night-fall/","https://openlibrary.org/works/OL22914W"]},{"type":"cover_front_review","sha256":"e9fd7fec4c53e2d7c94d3f0370ca9399b9c893a9e0e08b128ecbce7891da0337","cover_id":12313454,"reference":"cover-semantic-review-003.json","limitation":"Nelson DeMille/De crash readable; library label and1.28MB archived source retained as quality/performance limits."}],"cover_url":"https://covers.openlibrary.org/b/id/12313454-L.jpg?default=false","edition_id":987220006,"bound_title":"De crash","reviewed_at":"2026-11-02T21:50:56.327+00:00","bound_isbn13":"9789044313369","evidence_url":"https://www.abebooks.com/9789044313369/crash-N-Demille-9044313363/plp","review_batch":"nl-scale-20261102-021","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/12313454-M.jpg?default=false","bound_author_id":987320004},"before_row":null},{"key":{"work_id":987120002,"language":"nl"},"seq":14,"relation":"catalog_work_descriptions","after_row":{"text":"Een jongen groeit op in Indië en maakt daar een Japans kamp mee. Later volgen kostschooljaren in Nederland, de eerste ervaringen met meisjes en een huwelijk. Jeroen Brouwers verbindt die perioden niet alleen tot een levensloop, maar onderzoekt vooral welke gebeurtenissen iemand blijven vormen. Herinneringen aan verschillende plaatsen en leeftijden grijpen in elkaar. De roman maakt zichtbaar hoe een persoonlijkheid ontstaat uit ervaringen waarop iemand later steeds opnieuw terugkijkt, zonder dat het verleden daarmee een eenvoudig afgesloten geheel wordt.","work_id":987120002,"evidence":[{"note":"Same1988JeroenBrouwers novel and exactISBN9789029507516; source author OL55572A and KBp068890265 shareQ944323,VIAF84492073,ISNI0000000109204980. Three independent exactISBN physical listings identify first1988printing as hardcover with dustjacket, resolving cachedOLPaperback error. Distinct paperback ISBNs9789029507523/9789029507578 are not substituted.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p048709735"],"reference":"work:3216","checked_at":"2026-11-02T21:50:56.327Z","print_format_review":{"format":"hardcover","isbn13":"9789029507516","reason":"Three independently held physical copies for exactISBN9029507519/9789029507516 are hardbound1988firstprints with dustjacket; cached Paperback rejected.","sources":["https://www.demacker.nl/portfolio/brouwers.html","https://www.boekwinkeltjes.nl/b/225782677/De-Zondvloed/"],"editionKey":"/books/OL1785184M","originalEditionSha256":"0d6a42296e6b3005188b5b73becdac91164ae9c39112c05b21e5fcedeada2c7c"},"canonical_name_r